float estimerDistanceGrilleAccrochee(vec3 position, vec3 positionMasse, float temps) {
    vec3 positionGrille = position * (1.0 + 0.03 * sin(temps * 0.5));

    vec3 versMasse = positionMasse - positionGrille;
    float distanceAttraction = length(versMasse);
    float forceDistorsion = 1.2 / (distanceAttraction * distanceAttraction + 0.2);

    positionGrille = positionGrille + normalize(versMasse) * forceDistorsion;

    vec3 celluleRepetee = fract(positionGrille) - 0.5;
    float epaisseurBarre = 0.02;

    float axeX = length(celluleRepetee.yz) - epaisseurBarre;
    float axeY = length(celluleRepetee.xz) - epaisseurBarre;
    float axeZ = length(celluleRepetee.xy) - epaisseurBarre;

    return min(min(axeX, axeY), axeZ);
}

float estimerDistanceScene(vec3 position, vec3 positionMasse, float temps) {
    float distanceGrille = estimerDistanceGrilleAccrochee(position, positionMasse, temps);
    float distanceSphereMasse = length(position - positionMasse) - 0.3;

    return min(distanceGrille, distanceSphereMasse);
}

vec3 calculerNormaleGradiee(vec3 position, vec3 positionMasse, float temps) {
    vec2 epsilon = vec2(0.005, 0.0);

    float distanceCentre = estimerDistanceScene(position, positionMasse, temps);
    float distanceX = estimerDistanceScene(position - epsilon.xyy, positionMasse, temps);
    float distanceY = estimerDistanceScene(position - epsilon.yxy, positionMasse, temps);
    float distanceZ = estimerDistanceScene(position - epsilon.yyx, positionMasse, temps);

    return normalize(distanceCentre - vec3(distanceX, distanceY, distanceZ));
}

void mainImage(out vec4 couleurFragment, in vec2 coordFragment) {
    vec2 uvNormalisees = (coordFragment - 0.5 * iResolution.xy) / iResolution.y;
    float temps = iTime;

    float tempsCamera = temps * 0.2;
    vec3 origineRayon = vec3(5.0 * sin(tempsCamera), 3.0, 5.0 * cos(tempsCamera));
    vec3 pointCible = vec3(0.0, 0.0, 0.0);

    vec3 axeAvant = normalize(pointCible - origineRayon);
    vec3 axeDroit = normalize(cross(vec3(0.0, 1.0, 0.0), axeAvant));
    vec3 axeHaut = cross(axeAvant, axeDroit);
    vec3 directionRayon = normalize(axeAvant + uvNormalisees.x * axeDroit + uvNormalisees.y * axeHaut);

    vec3 positionMasse = vec3(
        sin(temps * 0.8) * 2.5,
        cos(temps * 0.4) * 1.0,
        cos(temps * 0.8) * 2.5
    );

    float distanceEtape = 0.0;
    for (int etape = 0; etape < 128; etape++) {
        vec3 positionCourante = origineRayon + directionRayon * distanceEtape;
        float distanceProche = estimerDistanceScene(positionCourante, positionMasse, temps);

        distanceEtape += distanceProche;
        if (distanceEtape > 30.0 || distanceProche < 0.001) break;
    }

    vec3 couleurFond = vec3(0.01, 0.02, 0.05);
    vec3 couleurFinale = couleurFond;

    if (distanceEtape < 30.0) {
        vec3 positionImpact = origineRayon + directionRayon * distanceEtape;

        vec3 normaleSurface = calculerNormaleGradiee(positionImpact, positionMasse, temps);

        float distanceMasse = length(positionImpact - positionMasse);
        vec3 directionLumiere = normalize(vec3(1.0, 2.0, -1.0));
        float eclairageDiffuse = max(dot(normaleSurface, directionLumiere), 0.1);

        vec3 couleurObjet = vec3(0.1, 0.6, 0.9) * eclairageDiffuse;
        if (distanceMasse < 0.31) {
            couleurObjet = vec3(1.0, 0.9, 0.7);
        }

        float luminescenceEnergie = 1.5 / (distanceMasse * distanceMasse * 5.0 + 0.1);
        couleurObjet += vec3(1.0, 0.6, 0.2) * luminescenceEnergie;

        couleurFinale = mix(couleurObjet, couleurFond, 1.0 - exp(-0.05 * distanceEtape));
    }

    couleurFinale = pow(couleurFinale, vec3(0.4545));
    couleurFragment = vec4(couleurFinale, 1.0);
}
